sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') return;

    var name = newValue.trim().toLowerCase();

    var baseValidator = new GlideAjax("BaseValidatorUtils");
    baseValidator.addParam("sysparm_name",      "checkDuplicateName");
    baseValidator.addParam("sysparm_base_name", name);

    baseValidator.getXMLAnswer(function(response) {
        if (response === 'true') {
            g_form.addErrorMessage("A base with this name already exists.");
            g_form.clearValue("name");
        }
    });
}
